551	
552	            do {
553	                let (data, response) = try await URLSession.shared.data(from: url)
554	                guard let httpResponse = response as? HTTPURLResponse,
555	                      (200..<300).contains(httpResponse.statusCode),
556	                      !data.isEmpty,
557	                      data.count <= 2_500_000 else {
558	                    continue
