567	    private func resolveAddresses(for dashboard: NinebotDashboard, force: Bool) async throws {
568	        let geocoder = AppleReverseGeocoder()
569	        var nextAddresses = resolvedAddresses
570	        var didResolve = false
571	        var lastError: Error?
572	        var sawCoordinate = false
573	
574	        for snapshot in dashboard.vehicles {
575	            guard let latitude = snapshot.state.latitude,
576	                  let longitude = snapshot.state.longitude else {
577	                continue
578	            }
579	
580	            sawCoordinate = true
581	            if !force, let cached = nextAddresses[snapshot.vehicle.sn],
582	               isFreshAddress(cached, latitude: latitude, longitude: longitude) {
583	                continue
584	            }
585	
586	            do {
587	                let geocodeCoordinate = NinebotCoordinateTransform.gcj02Coordinate(latitude: latitude, longitude: longitude)
588	                let address = try await geocoder.reverseGeocode(
589	                    latitude: geocodeCoordinate.latitude,
590	                    longitude: geocodeCoordinate.longitude
591	                )
592	                nextAddresses[snapshot.vehicle.sn] = NinebotResolvedAddress(
593	                    sn: snapshot.vehicle.sn,
594	                    address: address,
595	                    latitude: latitude,
596	                    longitude: longitude,
597	                    updatedAt: Date(),
598	                    source: Self.addressGeocodingSource
599	                )
600	                didResolve = true
601	            } catch {
602	                lastError = error
603	            }
604	        }
605	
606	        resolvedAddresses = nextAddresses
607	        store.saveResolvedAddresses(nextAddresses)
608	
609	        if force, !didResolve {
610	            if let lastError {
611	                throw lastError
612	            }
613	            if !sawCoordinate {
614	                throw AppleGeocodingError.missingCoordinate
615	            }
616	        }
617	    }
