619	    private func isFreshAddress(
620	        _ address: NinebotResolvedAddress,
621	        latitude: Double,
622	        longitude: Double
623	    ) -> Bool {
624	        let sameCoordinate = abs(address.latitude - latitude) < 0.00001
625	            && abs(address.longitude - longitude) < 0.00001
626	        return sameCoordinate && Date().timeIntervalSince(address.updatedAt) < 15 * 60
627	    }
