707	private enum AppleGeocodingError: LocalizedError {
708	    case invalidResponse
709	    case missingCoordinate
710	
711	    var errorDescription: String? {
712	        switch self {
713	        case .invalidResponse:
714	            return "Apple 地址解析返回无效"
715	        case .missingCoordinate:
716	            return "车辆暂未返回可解析的坐标"
717	        }
718	    }
719	}
720	
721	private struct AppleReverseGeocoder {
722	    func reverseGeocode(latitude: Double, longitude: Double) async throws -> String {
723	        let location = CLLocation(latitude: latitude, longitude: longitude)
724	        guard let request = MKReverseGeocodingRequest(location: location) else {
725	            throw AppleGeocodingError.invalidResponse
726	        }
727	        request.preferredLocale = Locale(identifier: "zh_CN")
728	
729	        let mapItems = try await request.mapItems
730	        let address = Self.addressText(from: mapItems.first)
731	        guard !address.isEmpty else {
732	            throw AppleGeocodingError.invalidResponse
733	        }
734	        return address
735	    }
736	
737	    private static func addressText(from mapItem: MKMapItem?) -> String {
738	        guard let mapItem else { return "" }
739	        let candidates = [
740	            mapItem.addressRepresentations?.fullAddress(includingRegion: true, singleLine: true),
741	            mapItem.address?.fullAddress,
742	            mapItem.address?.shortAddress,
743	            mapItem.name
744	        ]
745	
746	        return candidates
747	            .compactMap { $0?.trimmingCharacters(in: .whitespacesAndNewlines) }
748	            .first { !$0.isEmpty } ?? ""
749	    }
750	}
