import AppIntents
import SwiftUI

@main
struct mini_ninebotApp: App {
    @UIApplicationDelegateAdaptor(NinebotPushManager.self) private var pushManager

    init() {
        NinebotBackgroundTaskManager.register()
        NinebotBackgroundTaskManager.scheduleRefresh()
