    let record = NinebotLiveActivityPushTokenRecord(
        activityID: activityID,
        token: token,
        vehicleSN: cleanedSN,
        updatedAt: Date()
    )

    records.removeAll { existing in
        if existing.activityID == activityID {
            return true
        }
        if let cleanedSN, existing.vehicleSN == cleanedSN {
            defaults.removeObject(forKey: chargingLiveActivityPushTokenKey(activityID: existing.activityID))
