enum RecordingGPSQuality: Equatable {
    case waiting
    case stabilizing
    case good
    case weak
    case unavailable

    var title: String {
        switch self {
        case .waiting: return "等待 GPS"
        case .stabilizing: return "校准中"
        case .good: return "GPS 稳定"
        case .weak: return "GPS 弱"
        case .unavailable: return "定位不可用"
        }
    }

    var systemImage: String {
        switch self {
        case .waiting: return "location"
        case .stabilizing: return "scope"
        case .good: return "location.fill"
        case .weak: return "location.slash"
        case .unavailable: return "exclamationmark.triangle.fill"
        }
    }

    var tint: Color {
        switch self {
        case .waiting, .stabilizing: return Color.teslaSecondaryText
        case .good: return Color.teslaGreen
        case .weak: return .orange
        case .unavailable: return .red
        }
    }
}

@MainActor

